"""genui + Anthropic Messages API (Claude), streamed straight to OpenUI's React renderer.

Run:  pip install "genui-py[fastapi]" anthropic uvicorn
      ANTHROPIC_API_KEY=... uvicorn anthropic_app:app --reload --port 8000
"""
import os
from pathlib import Path

from anthropic import AsyncAnthropic
from fastapi import FastAPI, Request

from genui import Library
from genui.integrations.fastapi import read_run, stream_response

# spec.json is generated by the React frontend (`npm run generate` in examples/fastapi-react/frontend)
# from the same component library the renderer uses, so prompt and UI never drift apart.
SPEC = Path(__file__).resolve().parents[1] / "fastapi-react" / "backend" / "spec.json"
library = Library.from_spec(SPEC)
SYSTEM_PROMPT = library.system_prompt()

client = AsyncAnthropic()  # reads ANTHROPIC_API_KEY
MODEL = os.environ.get("MODEL", "claude-opus-5-5")

app = FastAPI()


@app.post("/api/chat")
async def chat(request: Request):
    run = await read_run(request)  # history from the UI, markers stripped, button clicks formatted
    # The Messages API takes the system prompt separately and only user/assistant turns.
    messages = [{"role": m["role"], "content": m["content"]}
                for m in run.messages if m["role"] in ("user", "assistant") and m["content"]]
    stream = await client.messages.create(
        model=MODEL,
        max_tokens=64000,
        system=SYSTEM_PROMPT,
        messages=messages,
        stream=True,
    )
    return stream_response(stream, run=run)  # Anthropic events -> AG-UI events
